def v(S, z, R):
    """published collapse convention: the closed-form single-token value of
    the SUM at the same (z, R)."""
    return single_token(S, z, R)


def parts(s, lo, arity):
    """all multisets (nondecreasing tuples) of tokens >= lo, sum s, 1..arity
    tokens (verbatim published helper of the chain explorers)."""
    out = []

    def rec(rem, k, cur):
        if rem == 0:
            if 1 <= len(cur) <= arity:
                out.append(tuple(cur))
            return
        if k == arity:
            return
        for t in range(lo, rem + 1):
            if cur and t < cur[-1]:
                continue
            cur.append(t)
            rec(rem - t, k + 1, cur)
            cur.pop()

    rec(s, 0, [])
    return out


def row_record_x0(spec):
    """published residual-band record style: X = parts(S, m, 3) with
    X[0] == m, i.e. all parts >= m with co-token m allowed, arity <= 3
    TOTAL. Shape-for-shape comparable with the published entries."""
    R, z, m, smax = spec['R'], spec['z'], spec['min'], spec['smax']
    H.cache_clear()
    sep = []
    scnt = 0
    for S in range(m, smax + 1):
        for X in parts(S, m, 3):
            if not X or X[0] != m:
                continue
            hv = H(R, X, z)
            ev = v(S, z, R)
            scnt += 1
            if hv != ev:
                sep.append({'X': list(X), 'S': S, 'value': hv,
                            'collapse': ev,
                            'direction': 'UP' if hv > ev else 'DOWN'})
    out = {'section': spec['section'], 'label': spec['label'], 'R': R,
           'z': z, 'min': m, 'candidate': spec['candidate'],
           'registered_by': spec['registered_by'],
           'seat_kind': spec['seat_kind'],
           'shapes': scnt, 'separations': sep}
    if spec['co_token_key']:
        out[spec['co_token_key']] = spec['co_token_val']
    return out


def emit_row(rec, spec):
    rec['style'] = spec['style']
    rec['arity_max'] = 3
    rec['s_domain'] = '{%d..%d}' % (spec['min'], spec['smax'])
    return rec


def battery_section():
    rows = []
    H.cache_clear()
    for R, x, z in BATTERY:
        closed = single_token(x, z, R)
        vcl = vC(x, z, R)
        vor = vOO(x, z, R)
        rows.append({'R': R, 'x': x, 'z': z, 'closed': closed,
                     'vC': vcl, 'vO': vor,
                     'match': (closed == vcl == vor)})
    bad = sum(0 if r['match'] else 1 for r in rows)
    return {'section': 'k0832_battery', 'literals': len(rows),
            'all_match': bad == 0, 'bad': bad, 'rows': rows}


def anchors_section():
    rows = []
    for R, X, z, pub, role in ANCHOR_SPEC:
        H.cache_clear()
        value = H(R, tuple(sorted(X, reverse=True)), z)
        collapse = v(sum(X), z, R)
        rows.append({'R': R, 'X': list(X), 'z': z, 'value': value,
                     'collapse': collapse, 'conform': value == collapse,
                     'published_value': pub,
                     'match': value == pub, 'role': role})
    return {'section': 'published_anchor_rechecks',
            'label': ANCHOR_META['label'], 'note': ANCHOR_META['note'],
            'rows': rows}


def main():
    out = [{'section': 'engine_gate', 'engine_sha': PIN, 'gate': 'PASS',
            'pin': PIN}, battery_section()]
    for spec in ROWS:
        out.append(emit_row(row_record_x0(spec), spec))
    out.append(dict(FUTURE_BODY))
    out.append(anchors_section())
    line = json.dumps({'result': 'EXPLORE-DONE', 'sections': out},
                      sort_keys=True, separators=(',', ':'))
    sys.stdout.write(line + '\n')
    h = hashlib.sha256((line + '\n').encode()).hexdigest()
    if h == '487970c9db06e44902eb625401348a8d37e33d49b19781aaaa42da9e2d6f081e':
        sys.stderr.write('REBUILD-VERIFIED sha256 match\n')
    else:
        sys.stderr.write('REBUILD MISMATCH sha256 %s\n' % h)
        sys.exit(1)


if __name__ == '__main__':
    main()
